<?php
namespace qqworld_collector\module\collecting; use qqworld_collector\lib; class auto_login extends lib { public function init() { add_filter( 'qqworld-collector-parse-headers-by-auto-login', array($this, 'parse_header_by_auto_login'), 10, 2 ); } public function login($website) { extract($website); $args = array( 'sslverify' => false ); if (isset($headers) && $headers) { $args['headers'] = array(); $headers = explode("\r\n", $headers); foreach ($headers as $header) { $header = explode(': ', $header); $args['headers'][$header[0]] = $header[1]; } } if ((isset($raw_data) && $raw_data) || (isset($fields) && $fields)) { switch ($data_type) { case 'raw': $args['body'] = stripslashes($raw_data); break; case 'form-data': default: if (isset($fields) && $fields) { $args['body'] = array(); foreach ($fields as $field) { $args['body'][$field['name']] = $field['value']; } } break; } $response = wp_remote_post($url, $args); } else { $response = wp_remote_get($url, $args); } if (!is_wp_error($response)) { $cookies = wp_remote_retrieve_header($response, 'set-cookie'); if (!empty($cookies)) { if (is_string($cookies)) $cookies = array($cookies); foreach ($cookies as &$cookie) $cookie = preg_replace('/;.*/i', ';', $cookie); } } else { $cookies = ''; } return $cookies; } public function parse_header_by_auto_login($headers, $guid) { if ($guid && isset($this->options->qc_auto_login_website[$guid])) { $website = $this->options->qc_auto_login_website[$guid]; $cookies = get_transient( 'qqworld-collector-auto-login-cookies-'.$guid ); if (empty($cookies)) { $cookies = $this->login($website); if ($cookies) { set_transient( 'qqworld-collector-auto-login-cookies-'.$guid, $cookies, $website['expires'] ); } } if ($cookies) { $headers = explode("\r\n", $headers); $has_cookie = false; if (!empty($headers)) foreach ($headers as &$header) { if (preg_match('/^Cookie:/i', $header)) { $has_cookie = true; foreach ($cookies as $cookie) { $cookie_arr = explode('=', $cookie); $pattern = $this->encode_pattern($cookie_arr[0]); if (preg_match('/'.$pattern.'=/i', $header)) { $header = preg_replace('/'.$pattern.'=[^;]*?;/', $cookie, $header); } else { $header .= ' ' . $cookie; } } break; } } if (!$has_cookie) { $new_cookies = 'Cookie:'; foreach ($cookies as $cookie) $new_cookies .= ' ' . $cookie; $headers[] = $new_cookies; } $headers = array_filter($headers); $headers = implode("\r\n", $headers); } } return $headers; } } ?>